"""Set a project up and keep its generated files current.

auto() is the entry point every trigger calls (session start, each prompt, cd,
git hooks). It returns in a few milliseconds when nothing changed and never
raises: a failed trigger must not break a shell, a commit or a session.

Two modes:
  full   a folder without git, or a git repo on the user's trust list. The block
         goes into AGENTS.md, CLAUDE.md imports it, and fieldbook is set up once
         git exists.
  local  every other git repo. No tracked file is touched: the block goes into
         .harness/AGENTS.md, CLAUDE.local.md imports it, both are listed in the
         repo's info/exclude, and fieldbook is not run.

Nothing inside a repository can prove whose it is, so a repo is trusted only when
the user said so (`harness trust`) or the engine itself set the folder up before
it had git. Every project read and write goes through safefs and every git call
through gitsafe, so a hostile folder cannot redirect the engine or make git run code.
"""
from __future__ import annotations

import contextlib
import fcntl
import hashlib
import json
import os
import re
import stat
import subprocess
import time
import unicodedata
from pathlib import Path

from . import BASE, DATA, ENGINE_VERSION, SHARED, decide, gitsafe, harness_off, project, safefs, tokens

BEGIN = "<!-- BEGIN ai-dotfiles:harness -->"
END = "<!-- END ai-dotfiles:harness -->"
IMPORT_BEGIN = "<!-- BEGIN ai-dotfiles:import -->"
IMPORT_END = "<!-- END ai-dotfiles:import -->"
HEADER = "# Agent rules\n\nInstructions for any AI agent working in this repository.\n\n"
LOCAL_HEADER = "# Project harness (local)\n\nGenerated by ai-dotfiles. Not committed: listed in the repo's info/exclude.\n\n"
DECISIONS_TEMPLATE = "# Decisions\n\nOne dated line per decision: what was decided, why, and what was rejected.\n\n"
CHANGELOG_TEMPLATE = "# Harness changelog\n\nSetup and updates made automatically by the ai-dotfiles engine. Newest last.\n\n"
CHANGELOG_LINE = re.compile(r"^- \d{4}-\d{2}-\d{2} (setup \(|update: |retired: )")
EXCLUDE_MARK ="# ai-dotfiles (local harness)"
EXCLUDE_END = "# end ai-dotfiles"
LOCAL_EXCLUDES = (".harness/", "CLAUDE.local.md", ".harness-skip")
IMPORT_LINE = re.compile(r"(?m)^[ \t]*@\.?/?AGENTS\.md[ \t]*$")
SHA = re.compile(r"^[0-9a-f]{40}([0-9a-f]{24})?$")
FIELDBOOK_RETRY_SECONDS = 6 * 3600
FIELDBOOK_TIMEOUT = {"session": 20, "cd": 60, "manual": 120}   # never from "prompt" (10 s hook) or "git" (fresh clone)
# Paths fieldbook writes. It follows symlinks, so it is not run when one of these, or anything
# inside one of the folders, is a symlink.
FIELDBOOK_FILES = ("AGENTS.md", "CLAUDE.md", "GEMINI.md", ".gitignore", ".windsurfrules", ".cursorrules",
                   ".clinerules", ".aider.conf.yml")
FIELDBOOK_DIRS = (".fieldbook", ".cursor", ".github", ".junie", ".clinerules", ".claude", ".gemini", ".git/hooks")
FIELDBOOK_WALK_LIMIT = 3000
UNDECIDED_RETRY_SECONDS = 3600
MAX_COMMANDS_WHEN_OVER = 4
FIELDBOOK_OVERRIDE = None         # tests point this at a stand-in binary


def _load(path, default):
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, type(default)) else default
    except (OSError, ValueError):
        return default


def _key(root):
    """Identity of a folder by device and inode, so a new folder at an old path starts fresh
    and one folder reached through different letter case shares one state."""
    ident = project.identity(root)
    return ident if ident else hashlib.sha1(str(root).encode()).hexdigest()[:16]


def _state_path(root):
    return DATA / "projects" / (_key(root) + ".json")


def _load_state(root):
    """The project's state. A state file written by the first release (keyed by the path's
    hash) is read once and carried over, so a block you removed back then stays removed."""
    path = _state_path(root)
    if path.exists():
        state = _load(path, {})
        was = state.get("root")
        # A disk may reuse a deleted folder's identity. If the folder this state was written
        # for still exists somewhere else, this is a different folder: start fresh.
        if isinstance(was, str) and was != str(root) and os.path.isdir(was) and not project._same(was, root):
            return {}
        return state
    legacy = DATA / "projects" / (hashlib.sha1(str(root).encode()).hexdigest()[:16] + ".json")
    old = _load(legacy, {})
    if not old:
        return {}
    carried = {k: old[k] for k in ("setup", "removed", "mode", "tags", "commands", "set_up_at") if k in old}
    try:
        _save_state(path, carried)       # written under the new key first, so it is never lost between the two
        os.remove(legacy)
    except OSError:
        pass
    return carried


def _save_state(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = "%s.%d.tmp" % (path, os.getpid())
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh)
    os.replace(tmp, path)


@contextlib.contextmanager
def _locked(root):
    """One setup per project at a time. The kernel drops the lock when a process dies."""
    path = DATA / "locks" / (_key(root) + ".lock")
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(str(path), os.O_CREAT | os.O_RDWR, 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            yield False
            return
        try:
            yield True
        finally:
            fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


# --- trust -------------------------------------------------------------------

def is_trusted(root):
    return project.is_trusted(root, project.load_trusted(SHARED / "trusted"))


def _repo(root):
    """The git repository holding root (root itself, or a folder above it inside home), or None."""
    return project.enclosing_repo(root)


def _layout(root):
    repo = _repo(root)
    return project.git_layout(repo) if repo is not None else None


def trust(root):
    """List a folder as trusted, with its identity. Returns False when it already is."""
    path = SHARED / "trusted"
    real = str(project.canonical(root))
    if not real.isprintable():
        raise ValueError("control character in the path")
    ident = project.identity(real)
    listed = project.load_trusted(path)
    if real in listed and listed[real] == ident:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        lines = path.read_text(encoding="utf-8").rstrip("\n").split("\n")
    except OSError:
        lines = ["# Projects that are yours. In these, the engine may write tracked files (AGENTS.md,",
                 "# CLAUDE.md) and run fieldbook. One folder per line; harness trust adds the folder's",
                 "# identity after a tab, so another folder that later takes the same path is not trusted."]
    lines = [l for l in lines if not l.strip() or l.lstrip().startswith("#")
             or str(project.canonical(os.path.expanduser(l.partition("\t")[0].strip()))) != real]
    lines.append("%s\t%s" % (real, ident))
    tmp = "%s.%d.tmp" % (path, os.getpid())
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")
    os.replace(tmp, path)
    return True


def untrust(root):
    path = SHARED / "trusted"
    real = str(project.canonical(root))
    try:
        lines = path.read_text(encoding="utf-8").rstrip("\n").split("\n")
    except OSError:
        return False
    kept = [l for l in lines if not l.strip() or l.lstrip().startswith("#")
            or str(project.canonical(os.path.expanduser(l.partition("\t")[0].strip()))) != real]
    if len(kept) == len(lines):
        return False
    path.write_text("\n".join(kept) + "\n", encoding="utf-8")
    return True


INIT_ENTRIES = {"HEAD", "config", "description", "hooks", "info", "objects", "refs", "logs", "index",
                "COMMIT_EDITMSG", "branches"}
INIT_CONFIG_KEYS = {"repositoryformatversion", "filemode", "bare", "logallrefupdates", "ignorecase",
                    "precomposeunicode", "symlinks"}


def _fresh_init(root):
    """True when root/.git looks like what `git init` just made here: nothing fetched, cloned,
    unpacked or configured. A .git that came from somewhere else is not the user's own work,
    whatever folder it landed in."""
    dot = Path(root) / ".git"
    if project.git_layout(root) != (dot, dot):
        return False
    raw = safefs.read_small(dot / "config", 65536)
    if raw is None:
        return False
    section = ""
    for line in raw.decode("utf-8", "replace").split("\n"):
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            section = line.strip("[]").strip().lower()
            if section != "core":
                return False              # a remote, a filter, an include: not a bare init
        elif section != "core" or line.split("=", 1)[0].strip().lower() not in INIT_CONFIG_KEYS:
            return False
    # Only what `git init` and local commits create. Anything else (commondir, which makes git
    # read another folder's config; worktrees; alternates; fetched or packed refs) is not ours.
    try:
        with os.scandir(dot) as entries:
            top = {e.name for e in entries}
    except OSError:
        return False
    try:
        with os.scandir(dot / "info") as entries:      # absent when the user's template has no info folder
            info = {e.name for e in entries}
    except OSError:
        info = set()
    if not top <= INIT_ENTRIES or not info <= {"exclude"}:
        return False
    for name in ("refs/remotes", "objects/info/alternates", "objects/info/http-alternates"):
        if os.path.lexists(dot / name):
            return False
    for name in INIT_ENTRIES:
        if os.path.islink(dot / name):
            return False
    try:
        with os.scandir(dot / "refs" / "heads") as entries:
            has_branch = any(True for _ in entries)
    except OSError:
        return False
    if has_branch and not os.path.isfile(dot / "logs" / "HEAD"):
        return False                      # commits with no record of how they got here
    if os.path.lexists(dot / "logs" / "HEAD"):
        raw = safefs.read_small(dot / "logs" / "HEAD", 1000000)     # never a FIFO or device, never unbounded
        if raw is None:
            return False
        moves = [l.partition("\t")[2] for l in raw.decode("utf-8", "replace").split("\n") if l.strip()]
        if any(not m.startswith("commit") for m in moves):
            return False                  # a pull, merge, checkout or reset happened
    # Hooks: only the samples git ships and the ones in the user's own template.
    template = Path.home() / ".git-templates" / "hooks"
    try:
        with os.scandir(dot / "hooks") as entries:
            names = [e.name for e in entries if not e.name.endswith(".sample")]
    except OSError:
        names = []
    for name in names:
        mine = safefs.read_small(template / name, 200000)
        if os.path.islink(dot / "hooks" / name) or mine is None or mine != safefs.read_small(dot / "hooks" / name, 200000):
            return False
    return True


def _born_here(root, state):
    """True when .harness/.born still holds the random token the engine wrote when it set this
    folder up without git. A repository cloned to the same path later cannot contain it."""
    token = state.get("born_token")
    text = safefs.read_text(root, Path(root) / ".harness" / ".born")
    return bool(token) and text is not None and text.strip() == token


# --- marked blocks -------------------------------------------------------------

def block_state(text, begin, end):
    """absent, ok, or damaged (markers missing, repeated or out of order)."""
    nb, ne = text.count(begin), text.count(end)
    if nb == 0 and ne == 0:
        return "absent"
    if nb == 1 and ne == 1 and text.index(begin) < text.index(end):
        return "ok"
    return "damaged"


def upsert_block(root, path, begin, end, body, header=""):
    """Replace the marked block, or append one. Returns created, updated, kept, damaged or unsafe.

    Text outside the markers is never touched. A file with damaged markers, or one that
    is not valid UTF-8, is left alone entirely.
    """
    if safefs.exists(root, path):
        text = safefs.read_text(root, path)
        if text is None:
            return "unsafe"
        existed = True
    else:
        text, existed = header, False
    block = "%s\n%s\n%s" % (begin, body.strip(), end)
    state = block_state(text, begin, end)
    if state == "damaged":
        return "damaged"
    if state == "ok":
        head, rest = text.split(begin, 1)
        new = head + block + rest.split(end, 1)[1]
    else:
        sep = "" if not text or text.endswith("\n\n") else ("\n" if text.endswith("\n") else "\n\n")
        new = text + sep + block + "\n"
    if existed and new == text:
        return "kept"
    try:
        safefs.write_text(root, path, new)
    except (safefs.Unsafe, OSError):
        return "unsafe"
    return "updated" if existed else "created"


def remove_block(root, path, begin, end):
    """Remove the marked block. The text around it is kept, with one blank line where the block was."""
    text = safefs.read_text(root, path)
    if text is None or block_state(text, begin, end) != "ok":
        return False
    head, rest = text.split(begin, 1)
    rest = rest.split(end, 1)[1]
    head, rest = head.rstrip("\n"), rest.lstrip("\n")
    new = head + ("\n\n" if head and rest else "") + rest
    if new.strip() and new.strip() not in (HEADER.strip(), LOCAL_HEADER.strip()):
        safefs.write_text(root, path, new.rstrip("\n") + "\n")
    else:
        safefs.remove(root, path)
    return True


def _append(root, path, template, line):
    text = safefs.read_text(root, path)
    if text is None:
        if safefs.exists(root, path):
            return False
        text = template
    safefs.write_text(root, path, text + line + "\n")
    return True


def build_block(tags, commands, pm, decisions_ref, workspace=None):
    """The generated block. Per-tag lines are dropped, then commands shortened, to stay within the cap."""
    cfg = _load(BASE / "config" / "project-rules.json", {})
    cap = _load(BASE / "config" / "harness-budgets.json", {}).get("project_block", 600)
    dos = list(cfg.get("universal", {}).get("do", []))
    donts = list(cfg.get("universal", {}).get("dont", []))
    extra_do, extra_dont = [], []
    for tag in tags:
        extra_do += cfg.get("tags", {}).get(tag, {}).get("do", [])
        extra_dont += cfg.get("tags", {}).get(tag, {}).get("dont", [])
    domains = ["security", "testing"] + [t for t in ("nodejs", "python", "java", "kotlin") if t in tags
                                         or (t == "nodejs" and {"javascript", "typescript", "react"} & set(tags))]
    domains = list(dict.fromkeys(domains))
    cmds = dict(commands)

    def render():
        lines = ["## Project harness", "",
                 "Generated by ai-dotfiles from this project's files and rewritten when they change.",
                 "Write your own rules outside this block.", ""]
        if workspace:
            lines.append("This folder is a workspace. The code is in `%s/`." % workspace)
        if tags:
            lines.append("Stack: %s%s" % (", ".join(tags), " (%s)" % pm if pm else ""))
        else:
            lines.append("Stack: not detected yet. This block fills in when a manifest appears.")
        lines.append("")
        if cmds:
            lines.append("Commands:")
            lines += ["- %s: `%s`" % (k, v) for k, v in cmds.items()]
        else:
            lines.append("Commands: none defined in the project files yet.")
        shown = [x for x in dos if "test" in cmds or "test command above" not in x]
        lines += ["", "Do:"] + ["- " + x for x in shown + extra_do]
        lines += ["", "Don't:"] + ["- " + x for x in donts + extra_dont]
        lines += ["", "Before a change, read the domain rules that match it: "
                  + ", ".join("~/.ai-rules/rules/domains/%s.md" % d for d in domains) + ".",
                  "Base rules are the machine-wide rules your tool already loads. If it loaded none, read ~/.ai-rules/RULES.md."]
        if decisions_ref:
            lines.append("Decisions: check %s before contradicting one, and record a new one there (dated: decision, reason, what was rejected) when a choice will still matter later." % decisions_ref)
        lines.append("Setup changes made by the engine are logged in .harness/CHANGELOG.md.")
        return "\n".join(lines)

    text = render()
    while tokens(text) > cap and (extra_do or extra_dont):
        if len(extra_dont) >= len(extra_do):
            extra_dont.pop()
        else:
            extra_do.pop()
        text = render()
    if tokens(text) > cap and len(cmds) > MAX_COMMANDS_WHEN_OVER:
        keep = [k for k in ("test", "build", "lint", "typecheck", "start", "dev", "format", "check") if k in cmds]
        cmds = {k: cmds[k] for k in keep[:MAX_COMMANDS_WHEN_OVER]}
        text = render()
    return text


# --- fieldbook -----------------------------------------------------------------

def find_fieldbook(manual=False):
    """Absolute fieldbook binary. PATH is never searched: a relative PATH entry could resolve inside a repo."""
    candidates = [FIELDBOOK_OVERRIDE]
    if manual:
        candidates.append(os.environ.get("FIELDBOOK_CMD"))
    try:
        candidates.append((SHARED / "fieldbook-path").read_text(encoding="utf-8").strip())
    except OSError:
        pass
    candidates.append(str(Path.home() / ".fieldbook" / "bin" / "fieldbook"))
    for c in candidates:
        try:
            if c and os.path.isabs(c) and os.path.isfile(c) and os.path.getsize(c) > 0 and os.access(c, os.X_OK):
                return c
        except OSError:
            continue
    return None


def _symlink_under(base):
    """The first symlink at or below base, "?" when there is too much to check, else None."""
    if os.path.islink(base):
        return base
    seen = 0
    for folder, dirs, files in os.walk(base, followlinks=False):
        for name in dirs + files:
            seen += 1
            if seen > FIELDBOOK_WALK_LIMIT:
                return "?"
            if os.path.islink(os.path.join(folder, name)):
                return os.path.join(folder, name)
    return None


def fieldbook_blocker(root):
    """Why fieldbook must not run here, or None. fieldbook follows symlinks and runs git itself."""
    layout = project.git_layout(root)
    if layout is None or layout[0] != Path(root) / ".git":
        return "the checkout is a worktree or submodule, or its .git is not a plain folder"
    for name in FIELDBOOK_FILES + FIELDBOOK_DIRS:
        found = _symlink_under(os.path.join(root, name))
        if found == "?":
            return "%s holds too many files to check for symlinks" % name
        if found:
            return "%s is a symlink" % os.path.relpath(found, root)
    hooks = gitsafe.run(root, "config", "--get", "core.hooksPath", harden=False)
    if hooks is None or hooks.returncode not in (0, 1) or hooks.stdout.strip():
        return "git has core.hooksPath set, so hooks belong to another tool"
    return None


def _run_fieldbook(fb, root, trigger):
    git = gitsafe.git_binary()
    path = os.pathsep.join(([os.path.dirname(git)] if git else []) + ["/usr/bin", "/bin", "/usr/sbin", "/sbin"])
    try:
        r = subprocess.run([fb, "init", "--yes"], cwd=str(root), capture_output=True, text=True,
                           timeout=FIELDBOOK_TIMEOUT[trigger], env=gitsafe.child_env(path), stdin=subprocess.DEVNULL)
    except subprocess.TimeoutExpired:
        return "fieldbook init timed out; retried later"
    except OSError as exc:
        return "fieldbook init failed to start: %s" % exc
    if r.returncode != 0:
        return "fieldbook init exited %d; retried later" % r.returncode
    return "fieldbook memory and logs initialized"


def _has_fieldbook(root):
    return (safefs.is_regular(root, root / ".fieldbook" / "config.yml")
            and safefs.is_regular(root, root / ".fieldbook" / "bank" / "04-decisions.md"))


def _fieldbook_due(root, mode, trigger, state):
    if mode != "full" or trigger not in FIELDBOOK_TIMEOUT or not os.path.lexists(root / ".git") \
            or os.path.lexists(root / ".fieldbook" / "config.yml"):
        return False
    return trigger == "manual" or time.time() - state.get("fb_attempt", 0) > FIELDBOOK_RETRY_SECONDS


def _carry_decisions(root):
    """Move decisions recorded before fieldbook existed into its bank, text unchanged."""
    src = root / ".harness" / "decisions.md"
    dst = root / ".fieldbook" / "bank" / "04-decisions.md"
    text = safefs.read_text(root, src)
    bank = safefs.read_text(root, dst)
    if text is None or bank is None:
        return False
    body = text[len(DECISIONS_TEMPLATE):] if text.startswith(DECISIONS_TEMPLATE) else text
    body = body.strip("\n")
    if body.strip():
        safefs.write_text(root, dst, bank.rstrip("\n") + "\n\n## Recorded before fieldbook was set up\n\n" + body + "\n")
    try:
        safefs.remove(root, src)
    except (safefs.Unsafe, OSError):
        safefs.write_text(root, src, DECISIONS_TEMPLATE)     # never carry the same text twice
    return bool(body.strip())


# --- git facts -----------------------------------------------------------------

# Every path setup, _prune_import and remove ask git about. One ls-files pass answers them all,
# so a slow listing is paid once per run instead of once per name on the prompt hook.
TRACKED_NAMES = (".harness", ".harness/AGENTS.md", ".harness/CHANGELOG.md", ".harness/decisions.md", ".harness/.born",
                 "CLAUDE.local.md", ".harness-skip", "AGENTS.md", "CLAUDE.md")
_tracked_memo = None                     # {root: {rel: tracked}} while a run is active, else None


@contextlib.contextmanager
def _one_scan():
    """Answer _tracked_any from one listing for the rest of this run. Nothing the engine writes
    changes the index, so an answer stays good until the run ends."""
    global _tracked_memo
    outer = _tracked_memo
    if outer is None:
        _tracked_memo = {}
    try:
        yield
    finally:
        if outer is None:
            _tracked_memo = None


def _tracked_any(root, rel):
    """True when git tracks the path or anything under it under any spelling the file system may
    treat as the same name, or cannot say (cautious). A pull can bring in .HARNESS/AGENTS.md or
    .harne\u017fs/AGENTS.md, which a folding disk writes into the existing .harness folder. git's
    icase pathspec folds ASCII only, so each tracked path is folded here the way _aliased folds
    names on disk."""
    if _tracked_memo is None:
        return _scan_tracked(root, [rel])[rel]
    answers = _tracked_memo.get(str(root))
    if answers is None or rel not in answers:
        answers = _tracked_memo[str(root)] = _scan_tracked(root, set(TRACKED_NAMES) | set(answers or ()) | {rel})
    return answers[rel]


def _scan_tracked(root, rels):
    """{rel: tracked} for every rel from a single ls-files pass, which stops once all are found."""
    wants = {rel: [_fold(c) for c in rel.split("/")] for rel in rels}
    pending = dict(wants)
    depth = max(len(w) for w in wants.values())
    tops = {w[0] for w in wants.values()}
    folded = {}

    def match(path):
        parts = path.split(b"/", depth)[:depth]
        top = folded.get(parts[0])           # top-level names repeat on every path below them
        if top is None:
            top = folded[parts[0]] = _fold(os.fsdecode(parts[0]))
        if top not in tops:
            return False
        names = [top] + [_fold(os.fsdecode(p)) for p in parts[1:]]
        for rel, want in list(pending.items()):
            if len(names) >= len(want) and names[:len(want)] == want:
                del pending[rel]
        return not pending

    found = gitsafe.scan(root, ["ls-files", "-z"], match)
    if found is None:
        return {rel: True for rel in rels}
    return {rel: rel not in pending for rel in rels}


def _fold(name):
    return unicodedata.normalize("NFKC", unicodedata.normalize("NFKC", name).casefold())


def _aliased(folder, names):
    """An entry of folder that the file system may treat as one of names under another
    spelling (".HARNESS", "claude.LOCAL.md", a long s), or None. git matches paths by exact
    bytes, so such an entry escapes both the tracked check and the info/exclude lines."""
    folder = Path(folder)
    inodes = set()
    for n in names:
        try:
            st = os.stat(folder / n, follow_symlinks=False)
            inodes.add((st.st_dev, st.st_ino))
        except OSError:
            pass
    folded = {_fold(n) for n in names}
    try:
        with os.scandir(folder) as entries:
            for e in entries:
                if e.name in names:
                    continue
                if _fold(e.name) in folded:
                    return e.name
                if inodes and any(e.inode() == ino for _, ino in inodes):
                    st = e.stat(follow_symlinks=False)
                    if (st.st_dev, st.st_ino) in inodes:
                        return e.name
    except OSError:
        return str(folder)                # cannot list it: cautious
    return None


def _ignored(root, rels):
    """True when git's ignore rules hide every one of rels, False when they do not, None when git cannot say."""
    r = gitsafe.run(root, "check-ignore", "--no-index", "--", *rels)
    if r is None or r.returncode not in (0, 1):
        return None
    return r.returncode == 0 and set(r.stdout.split("\n")) - {""} == set(rels)


def _head(root):
    r = gitsafe.run(root, "rev-parse", "-q", "--verify", "HEAD")
    out = r.stdout.strip() if r is not None and r.returncode == 0 else ""
    return out if SHA.match(out) else ""


def _reflog(root):
    """(path, size) of the checkout's reflog, or (None, 0)."""
    layout = _layout(root)
    if layout is None:
        return None, 0
    path = layout[0] / "logs" / "HEAD"
    try:
        st = os.lstat(path)
    except OSError:
        return None, 0
    return (path, st.st_size) if stat.S_ISREG(st.st_mode) else (None, 0)


def _matches_head(root, rel):
    """True when the working file is byte-identical to the committed one. Computed here,
    not with git diff or status, which can run a filter program named in the repo's config."""
    # "./" makes the path relative to the project folder, which may sit below the repository root.
    r = gitsafe.run(root, "rev-parse", "-q", "--verify", "HEAD:./%s" % rel)
    want = r.stdout.strip() if r is not None and r.returncode == 0 else ""
    data = safefs.read_bytes(root, Path(root) / rel)
    if not SHA.match(want) or data is None:
        return False
    h = hashlib.sha1() if len(want) == 40 else hashlib.sha256()
    h.update(b"blob %d\0" % len(data))
    h.update(data)
    return h.hexdigest() == want


def _came_from_git(root, rel, state):
    """True when a file's current content was put there by git, not by an edit of yours.

    That means: since the engine last wrote, the reflog shows a checkout, merge, pull,
    rebase or reset; no commit made in this checkout since then changed the file; and the
    file matches HEAD. Commits that arrived from elsewhere do not count as your edit.
    """
    path, size = _reflog(root)
    since = state.get("reflog", 0)
    if path is None or size == since:
        return False
    shrunk = size < since                 # the reflog was expired or collected: read all that is left
    if shrunk and _head(root) == state.get("head"):
        return False
    try:
        fd = os.open(str(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except OSError:
        return False
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            return False
        os.lseek(fd, max(0 if shrunk else since, size - 65536), os.SEEK_SET)
        entries = os.read(fd, 65536).decode("utf-8", "replace").splitlines()
    except OSError:
        return False
    finally:
        os.close(fd)
    moves = []
    for line in entries:
        meta, tab, message = line.partition("\t")
        parts = meta.split(" ")
        if tab and len(parts) >= 2:
            moves.append((parts[1], message))
    if not any(not m.startswith("commit") for _, m in moves):
        return False
    head = state.get("head", "")
    if SHA.match(head):
        log = gitsafe.run(root, "log", "--no-show-signature", "--format=%H", "%s..HEAD" % head, "--", rel)
        if log is None or log.returncode != 0:
            return False                  # git cannot say: treat the change as yours
        made_here = {sha for sha, m in moves if m.startswith("commit")}
        if made_here & set(log.stdout.split()):
            return False                  # you committed a change to this file yourself
    return _matches_head(root, rel)


def _exclude_file(root):
    """(git common dir, exclude path), or None when the git folder is not provably this checkout's."""
    layout = _layout(root)
    return (layout[1], layout[1] / "info" / "exclude") if layout else None


def _local_excludes(state):
    """The entries local mode lists in info/exclude. A CLAUDE.local.md that came with the folder
    is not the engine's to hide: it showed in git status before the engine arrived, and still does."""
    if state.get("shipped_claude_local"):
        return tuple(e for e in LOCAL_EXCLUDES if e != "CLAUDE.local.md")
    return LOCAL_EXCLUDES


def _hide_locally(root, entries=LOCAL_EXCLUDES):
    """List the local-mode files in info/exclude, inside a marked block. False when that is not possible."""
    target = _exclude_file(root)
    if target is None:
        return False
    gitdir, path = target
    try:
        text = safefs.read_text(gitdir, path)
        if text is None:
            if safefs.exists(gitdir, path):
                return False
            text = ""
        missing = [e for e in entries if e not in text.splitlines()]
        if missing:
            safefs.write_text(gitdir, path, text.rstrip("\n") + ("\n" if text else "")
                              + "\n".join([EXCLUDE_MARK] + missing + [EXCLUDE_END]) + "\n")
        return True
    except (safefs.Unsafe, OSError):
        return False


def _still_hidden(root):
    """True when the engine's block is still in this checkout's info/exclude."""
    target = _exclude_file(root)
    text = safefs.read_text(target[0], target[1]) if target else None
    return text is not None and EXCLUDE_MARK in text.split("\n")


def _unhide(root, keep=()):
    """Remove the engine's block from info/exclude, or cut it down to the entries in keep.
    The same lines written by you elsewhere stay."""
    target = _exclude_file(root)
    if target is None:
        return
    gitdir, path = target
    try:
        text = safefs.read_text(gitdir, path)
        if text is None:
            return
        lines, kept, i = text.splitlines(), [], 0
        while i < len(lines):
            if lines[i] == EXCLUDE_MARK:
                i += 1
                held = []
                while i < len(lines) and lines[i] in LOCAL_EXCLUDES:
                    if lines[i] in keep:
                        held.append(lines[i])
                    i += 1
                if i < len(lines) and lines[i] == EXCLUDE_END:
                    i += 1
                if held:
                    kept.extend([EXCLUDE_MARK] + held + [EXCLUDE_END])
                continue
            kept.append(lines[i])
            i += 1
        if len(kept) != len(lines):
            safefs.write_text(gitdir, path, "\n".join(kept) + ("\n" if kept else ""))
    except (safefs.Unsafe, OSError):
        pass


def _withdraw_local(root):
    """The repository's own ignore rules now show local files, and they outrank info/exclude,
    so hiding cannot work: delete what the engine generated, keep what you wrote, and keep the
    exclude block only while something of yours is left for it to hide."""
    def template_only(path):
        text = safefs.read_text(root, path)
        return text is not None and text.strip() == DECISIONS_TEMPLATE.strip()

    def engine_only(path):
        text = safefs.read_text(root, path)
        template = set(CHANGELOG_TEMPLATE.splitlines())
        return text is not None and all(l in template or CHANGELOG_LINE.match(l) for l in text.splitlines())

    for step in (lambda: remove_block(root, root / ".harness" / "AGENTS.md", BEGIN, END),
                 lambda: remove_block(root, root / "CLAUDE.local.md", IMPORT_BEGIN, IMPORT_END),
                 lambda: engine_only(root / ".harness" / "CHANGELOG.md")
                 and safefs.remove(root, root / ".harness" / "CHANGELOG.md"),
                 lambda: template_only(root / ".harness" / "decisions.md")
                 and safefs.remove(root, root / ".harness" / "decisions.md"),
                 lambda: safefs.rmdir(root, root / ".harness")):
        try:
            step()
        except (safefs.Unsafe, OSError):
            pass
    if not any(os.path.lexists(root / n) for n in (".harness", "CLAUDE.local.md", ".harness-skip")):
        _unhide(root)


# --- setup ---------------------------------------------------------------------

def _paths(root, mode):
    if mode == "local":
        return root / ".harness" / "AGENTS.md", root / "CLAUDE.local.md"
    return root / "AGENTS.md", root / "CLAUDE.md"


def _mtime(path):
    try:
        return os.lstat(path).st_mtime_ns
    except OSError:
        return None


def _retire(root, mode, notes):
    """Leaving a mode: remove what that mode wrote, unless git tracks it (then say so instead)."""
    target, importer = _paths(root, mode)
    for path, begin, end in ((target, BEGIN, END), (importer, IMPORT_BEGIN, IMPORT_END)):
        rel = str(path.relative_to(root))
        if not safefs.exists(root, path):
            continue
        if mode == "full" and _repo(root) is not None and _tracked_any(root, rel):
            notes.append("%s is tracked by git and still holds the old engine section; remove it if the team does not want it" % rel)
            continue
        try:
            remove_block(root, path, begin, end)
        except (safefs.Unsafe, OSError):
            notes.append("could not clean %s" % rel)
    if mode == "local":
        # Your own CLAUDE.local.md (or .harness-skip) stays out of git after the switch.
        _unhide(root, keep=[n for n in ("CLAUDE.local.md", ".harness-skip") if os.path.lexists(root / n)])


def _fast_path(root, state, stamp0, trigger):
    """The action to return without locking, or None when setup has to run."""
    if state.get("stamp0") != stamp0 or state.get("engine") != ENGINE_VERSION:
        return None
    if state.get("root") and state["root"] != str(root):
        return None                       # moved or renamed: let setup record where it is now
    if state.get("removed"):
        return "removed-by-user"
    if state.get("blocked"):
        now_full = _repo(root) is None or is_trusted(root)
        if state.get("blocked_mode") != ("full" if now_full else "local"):
            return None                   # trust changed, or git appeared: the reason may be gone
        return state["blocked"] if _mtime(state.get("blocked_target", "")) == state.get("blocked_mtime") else None
    if state.get("declined"):
        upgraded = trigger in ("session", "prompt") and state.get("declined_trigger") not in ("session", "prompt")
        undecided = state.get("abstained") and trigger in ("session", "prompt") \
            and time.time() - state.get("declined_at", 0) > UNDECIDED_RETRY_SECONDS
        return None if (upgraded or undecided) else "declined"
    mode = state.get("mode", "full")
    if (mode == "full") != (_repo(root) is None or is_trusted(root)):
        return None                       # trust changed, or git appeared
    target, importer = _paths(root, mode)
    text = safefs.read_text(root, target)
    # The stamp does not cover .harness/AGENTS.md, so an "@" added outside its block is looked
    # for here. The import file is read only when one is found, so the usual run stays quick.
    if mode == "local" and text is not None and not _clean_outside_block(root, target, LOCAL_HEADER) \
            and "@.harness/AGENTS.md" in (safefs.read_text(root, importer) or ""):
        return None
    if state.get("setup") and text is not None and block_state(text, BEGIN, END) == "ok" \
            and not _fieldbook_due(root, mode, trigger, state) and (mode != "local" or _still_hidden(root)):
        return "current"
    return None


def _no_references(root, path):
    """True when path is a regular UTF-8 file in the project with no "@" in it at all.

    Claude Code can read text after an "@" as a file to load, and how its Markdown reader
    splits tokens (escapes, emphasis, e-mail-like runs) is its own business. So the engine
    does not try to tell references from other uses of "@": any "@" keeps the file out.
    """
    text = safefs.read_text(root, path)
    return text is not None and "@" not in text


def _write_import(root, mode, importer, state):
    """Make Claude Code load the block. Returns the upsert result, or skipped/left."""
    if os.path.islink(importer):
        return "skipped"
    if mode == "local":
        if state.get("shipped_claude_local"):
            return "shipped"
        # Checked on every run, not only at first setup: a pull or an edit since then can have
        # put text outside the block, and upsert_block keeps whatever is there.
        if state.get("shipped_local") or not _clean_outside_block(root, root / ".harness" / "AGENTS.md", LOCAL_HEADER):
            return "references"
        lines = ["@.harness/AGENTS.md"]
        # A CLAUDE.local.md stops Claude Code reading the repo's own AGENTS.md, which it
        # would otherwise load when there is no CLAUDE.md. Import it to keep that behavior.
        if _no_references(root, root / "AGENTS.md") and not any(
                safefs.exists(root, root / n) for n in ("CLAUDE.md", ".claude/CLAUDE.md")):
            lines.append("@AGENTS.md")
        return upsert_block(root, importer, IMPORT_BEGIN, IMPORT_END, "\n".join(lines))
    if _repo(root) is None and not state.get("seen_empty"):
        # A folder that arrived with its files (an unpacked download) is in full mode, but its
        # AGENTS.md is still someone else's: import it only if it holds no "@" of its own.
        text = safefs.read_text(root, root / "AGENTS.md") or ""
        head, _, rest = text.partition(BEGIN)
        if "@" in head + rest.partition(END)[2]:
            return "references"
    existing = safefs.read_text(root, importer)
    if existing is None:
        if safefs.exists(root, importer):
            return "unsafe"
        return upsert_block(root, importer, IMPORT_BEGIN, IMPORT_END, "@AGENTS.md")
    if IMPORT_BEGIN in existing or IMPORT_END in existing:
        return upsert_block(root, importer, IMPORT_BEGIN, IMPORT_END, "@AGENTS.md")
    if IMPORT_LINE.search(existing):
        return "left"                     # it already imports AGENTS.md itself
    if importer.name in state.get("imports_added", []):
        return "left"                     # you removed the import the engine added to this file
    return upsert_block(root, importer, IMPORT_BEGIN, IMPORT_END, "@AGENTS.md")


def _clean_outside_block(root, path, header=""):
    """True when path is a regular UTF-8 file in the project, its block markers are intact or
    absent, it starts with header, and it has no "@" outside the generated block."""
    text = safefs.read_text(root, path)
    if text is None or block_state(text, BEGIN, END) == "damaged" or not text.startswith(header):
        return False
    head, _, rest = text.partition(BEGIN)
    return "@" not in head + rest.partition(END)[2]


def _prune_import(root, mode, importer, state):
    """Before an early stop: take each line out of the engine's import block whose file no
    longer passes the check it passed when the line went in. A pull or an edit since then can
    have changed that file, and a stop never reaches _write_import to look again."""
    if os.path.islink(importer):
        return
    text = safefs.read_text(root, importer)
    if text is None or block_state(text, IMPORT_BEGIN, IMPORT_END) != "ok":
        return
    if mode == "local" and (state.get("shipped_claude_local") or _aliased(root, ("CLAUDE.local.md",)) is not None
                            or _tracked_any(root, "CLAUDE.local.md")):
        return                            # not a file the engine may write in this repository
    agents = root / "AGENTS.md"
    if mode == "local":
        local_ok = not state.get("shipped_local") and not _tracked_any(root, ".harness/AGENTS.md") \
            and _aliased(root, (".harness",)) is None and _aliased(root / ".harness", ("AGENTS.md",)) is None \
            and _clean_outside_block(root, root / ".harness" / "AGENTS.md", LOCAL_HEADER)
        allowed = {"@AGENTS.md": _no_references(root, agents), "@.harness/AGENTS.md": local_ok}
    elif _repo(root) is None and not state.get("seen_empty"):
        allowed = {"@AGENTS.md": _clean_outside_block(root, agents)}
    else:
        return                            # your own folder: its AGENTS.md is imported as it is
    lines = text.split(IMPORT_BEGIN, 1)[1].split(IMPORT_END, 1)[0].split("\n")
    lines = [l.strip() for l in lines if l.strip()]
    keep = [l for l in lines if allowed.get(l)]
    if keep == lines:
        return
    try:
        if keep:
            upsert_block(root, importer, IMPORT_BEGIN, IMPORT_END, "\n".join(keep))
        else:
            remove_block(root, importer, IMPORT_BEGIN, IMPORT_END)
    except (safefs.Unsafe, OSError):
        pass


def setup(root, trigger="manual", force=False):
    """Generate or refresh one project. Returns a result dict; never raises on a hostile tree."""
    with _one_scan():
        return _setup(Path(root), trigger, force)


def _setup(root, trigger, force):
    result = {"root": str(root), "action": "current", "notes": []}
    state_path = _state_path(root)
    if not force:
        quick = _fast_path(root, _load_state(root), project.stamp(root), trigger)
        if quick:
            result["action"] = quick
            return result

    with _locked(root) as got:
        if not got:
            result["action"] = "busy"
            return result
        state = _load_state(root)        # re-read inside the lock
        if force:
            for key in ("removed", "blocked", "blocked_target", "blocked_mtime", "blocked_mode", "declined", "abstained"):
                state.pop(key, None)
        stamp0 = project.stamp(root)
        repo = _repo(root)               # the repository holding this project; it may be a folder above
        git = repo is not None
        notes = result["notes"]

        # A folder the engine saw empty and set up before it had git was made on this machine: trust it.
        if repo == root and state.get("setup") and state.get("born_plain") and not state.get("born_trust_done") \
                and project.git_layout(root) is not None:
            state["born_trust_done"] = True
            earned = _born_here(root, state) and _fresh_init(root)
            try:
                if not _tracked_any(root, ".harness/.born"):             # decided once; a committed copy is left as it is
                    safefs.remove(root, root / ".harness" / ".born")
            except (safefs.Unsafe, OSError):
                pass
            if earned:
                if trust(root):
                    notes.append("trusted automatically: the engine set this folder up before it had git")
            else:
                notes.append("this folder now has a git repository that was not just made by `git init` here, "
                             "so it is not trusted automatically; run `harness trust` if it is yours")
        mode = "local" if git and not is_trusted(root) else "full"
        target, importer = _paths(root, mode)

        def stop(action, note=None, **extra):
            _prune_import(root, mode, importer, state)
            if note:
                notes.append(note)
            result["action"] = action
            kept = {k: v for k, v in state.items() if k not in ("blocked", "blocked_target", "blocked_mtime", "blocked_mode", "blocked_why")}
            if "blocked" in extra:
                extra.update(blocked_target=str(target), blocked_mtime=_mtime(target), blocked_mode=mode, blocked_why=note or "")
            _save_state(state_path, dict(kept, stamp0=stamp0, engine=ENGINE_VERSION, root=str(root), **extra))
            return result

        if state.get("removed") and not force:
            return stop("removed-by-user")

        if mode == "local":
            alias = _aliased(root, (".harness", "CLAUDE.local.md"))
            if alias is None and safefs.is_dir(root, root / ".harness"):
                alias = _aliased(root / ".harness", ("AGENTS.md", "CHANGELOG.md", "decisions.md", "config.json"))
            if alias is not None:
                return stop("skipped", "%r may be another spelling of a file local setup writes (this file system folds "
                            "letter case), and git would not see it as that file; skipped so no tracked or visible file "
                            "is changed" % alias, blocked="skipped")
            for rel in (".harness", "CLAUDE.local.md"):
                if _tracked_any(root, rel):
                    return stop("skipped", "%s is tracked by git, so local setup would change a tracked file; the engine leaves "
                                "this repository as committed. Run `harness trust` if it is yours" % rel, blocked="skipped")
            # A CLAUDE.local.md here before the engine's first local setup came with the folder, like
            # a shipped .harness/AGENTS.md: the engine neither writes into it nor hides it. Decided
            # before anything is written, and dropped once that file is gone.
            if not os.path.lexists(root / "CLAUDE.local.md"):
                state.pop("shipped_claude_local", None)
            elif not (state.get("setup") and state.get("mode") == "local") \
                    and "CLAUDE.local.md" not in state.get("imports_added", []):
                state["shipped_claude_local"] = True
            if not _hide_locally(root, _local_excludes(state)):
                return stop("skipped", "cannot list local files in this checkout's info/exclude; skipped so nothing shows as a change",
                            blocked="skipped")
            ours = [".harness/AGENTS.md", ".harness/CHANGELOG.md", ".harness/decisions.md", ".harness/config.json",
                    "CLAUDE.local.md", ".harness-skip"]
            if state.get("shipped_claude_local"):
                ours.remove("CLAUDE.local.md")
            hidden = _ignored(root, ours)
            if hidden is None:
                # A timeout or error is not evidence that the files show: withdrawing on it would
                # delete a working setup, and writing on it could put files in git status.
                return stop("skipped", "cannot tell whether this repository's ignore rules hide local files (git "
                            "check-ignore did not answer); skipped for now")
            if not hidden:
                _withdraw_local(root)
                return stop("skipped", "this repository's ignore rules un-ignore .harness/ or CLAUDE.local.md, so local "
                            "files would show up in git status; skipped", blocked="skipped")
            if state.get("setup") and state.get("mode") == "full":
                notes.append("this repository is not on your trust list, so the engine stopped writing tracked files here; "
                             "run `harness trust` if it is yours")

        present = safefs.exists(root, target)
        text = safefs.read_text(root, target)
        bstate = block_state(text, BEGIN, END) if text is not None else ("unsafe" if present else "absent")
        if bstate in ("damaged", "unsafe"):
            return stop(bstate, "%s: %s; file left untouched" % (
                target.relative_to(root), "block markers damaged" if bstate == "damaged"
                else "not a regular UTF-8 file, or unreadable"), blocked=bstate)

        # The block vanished from a file that still exists. If git put this version of the file
        # there (another branch, a pull), regenerate. Otherwise you deleted the block: stay out
        # until `harness init`.
        if state.get("setup") and state.get("mode") == mode and present and bstate == "absent" and not force:
            if not (git and _came_from_git(root, str(target.relative_to(root)), state)):
                return stop("removed-by-user", removed=True)

        if not state.get("setup") and not force and bstate != "ok" \
                and not (project.has_marker(root) or project.is_workspace(root)):
            shape = project.shape(root)
            d = decide.decide("is_project", {
                "code_files": min(shape["code_files"], 5) / 5.0,
                "has_src": int(shape["has_src"]),
                "session_trigger": int(trigger in ("session", "prompt")),
            }, ctx={"root": str(root), "trigger": trigger})
            if d["answer"] is not True:
                result["notes"].append("not treated as a project yet (p=%.2f)" % d["p"])
                result["action"] = "declined"
                _save_state(state_path, {"stamp0": stamp0, "engine": ENGINE_VERSION, "declined": True,
                                         "declined_trigger": trigger, "declined_at": int(time.time()),
                                         "abstained": d["answer"] is None,
                                         "seen_empty": bool(state.get("seen_empty")) or project.is_empty(root),
                                         **{k: state[k] for k in ("skip_override",) if k in state}})
                return result

        if state.get("setup") and state.get("mode") and state["mode"] != mode:
            _retire(root, state["mode"], notes)

        if _fieldbook_due(root, mode, trigger, state):
            state["fb_attempt"] = int(time.time())
            _save_state(state_path, dict(state))
            blocker = fieldbook_blocker(root)
            fb = None if blocker else find_fieldbook(manual=trigger == "manual")
            if blocker or fb is None:
                why = "fieldbook not run: %s" % blocker if blocker else "fieldbook binary not found; no project memory created"
                if state.get("fb_note") != why or trigger == "manual":
                    notes.append(why)
                state["fb_note"] = why
            else:
                state.pop("fb_note", None)
                notes.append(_run_fieldbook(fb, root, trigger))
                stamp0 = project.stamp(root)
        # A folder that arrived with its files may ship its own bank: its rules are not yours to
        # present as decisions, and your decisions do not belong in it.
        has_fieldbook = mode == "full" and (git or state.get("seen_empty")) and _has_fieldbook(root)
        if has_fieldbook:
            try:
                if _carry_decisions(root):
                    notes.append("earlier decisions moved into .fieldbook/bank/04-decisions.md")
            except (safefs.Unsafe, OSError):
                notes.append("could not move .harness/decisions.md into the fieldbook bank")

        # A .harness/AGENTS.md here before the engine's first local setup came with the folder
        # (a tarball that carries .git, say). Apply the same rule as to a downloaded AGENTS.md,
        # and keep applying it: the decision is made once, while the file is still theirs alone.
        if mode == "local" and not (state.get("setup") and state.get("mode") == "local") and present:
            head, _, rest = (text or "").partition(BEGIN)
            if "@" in head + rest.partition(END)[2] or not (text or "").startswith(LOCAL_HEADER):
                state["shipped_local"] = True

        tags = project.detect_tags(root)
        commands = project.detect_commands(root)
        code, _ = project.code_root(root)
        # The same holds for a .harness/decisions.md that was there before the engine's first setup
        # in a folder that is not yours: it is named only if the engine made it (or it is still the
        # engine's template). Decided once; a folder set up before this was recorded keeps its line.
        decisions_path = root / ".harness" / "decisions.md"
        own_decisions = state.get("decisions_own")
        if own_decisions is None:
            own_decisions = bool(state.get("setup")) or not safefs.exists(root, decisions_path) \
                or safefs.read_text(root, decisions_path) == DECISIONS_TEMPLATE
        state["decisions_own"] = own_decisions
        if has_fieldbook:
            decisions_ref = ".fieldbook/bank/04-decisions.md"
        elif own_decisions or (mode == "full" and (git or state.get("seen_empty"))):
            decisions_ref = ".harness/decisions.md"
        else:
            decisions_ref = None
            notes.append(".harness/decisions.md came with this folder, so the block does not point agents at it")
        block = build_block(tags, commands, project.package_manager(root), decisions_ref,
                            workspace=code.name if code != root else None)
        action = upsert_block(root, target, BEGIN, END, block, header=LOCAL_HEADER if mode == "local" else HEADER)
        if action in ("damaged", "unsafe"):
            return stop(action, "could not write %s safely" % target.relative_to(root), blocked=action)

        import_state = _write_import(root, mode, importer, state)
        if import_state == "references":
            try:
                remove_block(root, importer, IMPORT_BEGIN, IMPORT_END)     # an import added before the "@" appeared
            except (safefs.Unsafe, OSError):
                pass
            if mode == "local":
                notes.append(".harness/AGENTS.md has an \"@\" outside the generated block, does not start with the "
                             "engine's header, or came with this folder, so %s does not import it" % importer.name)
            else:
                notes.append("AGENTS.md came with this folder and has an \"@\" outside the generated block, so %s does "
                             "not import it" % importer.name)
        if import_state == "shipped":
            notes.append("CLAUDE.local.md came with this folder, so the engine leaves it as it is and does not hide it; "
                         "add @.harness/AGENTS.md to it yourself if you want Claude Code to load the block")
        if import_state in ("damaged", "unsafe"):
            notes.append("%s: could not add the import (%s); Claude Code will not see the block" % (importer.name, import_state))
        imports = set(state.get("imports_added", []))
        if import_state in ("created", "updated", "kept"):
            imports.add(importer.name)

        if decisions_ref == ".harness/decisions.md" and not safefs.exists(root, root / ".harness" / "decisions.md"):
            try:
                safefs.write_text(root, root / ".harness" / "decisions.md", DECISIONS_TEMPLATE)
            except (safefs.Unsafe, OSError):
                notes.append("could not create .harness/decisions.md")

        first = not state.get("setup")
        born_token = state.get("born_token")
        # Only a folder the engine saw empty first can earn trust later. An unpacked download
        # arrives full, so it never does.
        if first and not git and state.get("seen_empty"):
            born_token = os.urandom(16).hex()
            try:
                safefs.write_text(root, root / ".harness" / ".born", born_token + "\n")
            except (safefs.Unsafe, OSError):
                born_token = None
        if first:
            line = "setup (%s mode): stack %s; commands %s" % (mode, ", ".join(tags) or "none yet", ", ".join(commands) or "none yet")
        else:
            old_tags, old_cmds = set(state.get("tags", [])), state.get("commands", {})
            diffs = []
            if set(tags) != old_tags:
                diffs.append("stack %s" % " ".join(["+" + t for t in sorted(set(tags) - old_tags)]
                                                   + ["-" + t for t in sorted(old_tags - set(tags))]))
            if commands != old_cmds:
                diffs.append("commands now %s" % (", ".join(commands) or "none"))
            if mode != state.get("mode", mode):
                diffs.append("mode %s" % mode)
            line = "update: " + ("; ".join(diffs) if diffs else "block regenerated")
        if first or action != "kept" or notes:
            try:
                _append(root, root / ".harness" / "CHANGELOG.md", CHANGELOG_TEMPLATE,
                        "- %s %s" % (time.strftime("%Y-%m-%d"), line + "".join("; " + n for n in notes)))
            except (safefs.Unsafe, OSError):
                notes.append("changelog not writable")
            result["action"] = "setup" if first else "updated"
        result["block"] = block
        result["mode"] = mode
        new = {"setup": True, "stamp0": stamp0, "engine": ENGINE_VERSION, "mode": mode, "root": str(root),
               "tags": tags, "commands": commands, "head": _head(root) if git else "",
               "reflog": _reflog(root)[1] if git else 0, "set_up_at": state.get("set_up_at") or int(time.time()),
               "fb_attempt": state.get("fb_attempt", 0), "imports_added": sorted(imports),
               "born_plain": bool(state.get("born_plain")) or bool(first and not git and born_token)}
        if born_token:
            new["born_token"] = born_token
        for key in ("fb_note", "born_trust_done", "seen_empty", "shipped_local", "shipped_claude_local", "decisions_own"):
            if key in state:
                new[key] = state[key]
        if state.get("skip_override") and os.path.lexists(root / ".harness-skip"):
            new["skip_override"] = True      # dropped once the committed file is gone
        _save_state(state_path, new)
        return result


def _retire_if_set_up(folder):
    """A folder the engine once set up is no longer a project root (it now holds several
    projects, say). Take the engine's blocks out, so its rules stop loading into everything below."""
    folder = Path(folder)
    state_path = _state_path(folder)
    state = _load_state(folder)
    if not state.get("setup") or project.locate(folder)[0] == folder:
        return False
    with _locked(folder) as got:
        if not got:
            return False
        notes = []
        mode = state.get("mode", "full")
        _retire(folder, mode, notes)
        try:
            if mode == "local":
                # Someone else's repository: take the engine's files out, and keep whatever
                # is left (your own notes) hidden from git as before.
                safefs.remove(folder, folder / ".harness" / "CHANGELOG.md")
                decisions = safefs.read_text(folder, folder / ".harness" / "decisions.md")
                if decisions is not None and decisions.strip() == DECISIONS_TEMPLATE.strip():
                    safefs.remove(folder, folder / ".harness" / "decisions.md")
                if safefs.is_dir(folder, folder / ".harness") and not safefs.rmdir(folder, folder / ".harness"):
                    _hide_locally(folder, _local_excludes(state))
            else:
                _append(folder, folder / ".harness" / "CHANGELOG.md", CHANGELOG_TEMPLATE,
                        "- %s retired: this folder is no longer a single project%s"
                        % (time.strftime("%Y-%m-%d"), "".join("; " + n for n in notes)))
        except (safefs.Unsafe, OSError):
            pass
        try:
            os.remove(state_path)
        except OSError:
            pass
    return True


def auto(cwd, trigger):
    """Trigger entry point. Never raises."""
    try:
        if harness_off():
            return {"action": "off"}
        root, why = project.locate(cwd)
        if root is None:
            if why == "container" and _retire_if_set_up(project.canonical(cwd)):
                return {"action": "retired", "why": why}
            return {"action": "skip", "why": why}
        # A parent set up earlier (as a workspace, say) that has since become a folder of projects.
        home = project.home()
        for parent in root.parents:
            if parent == home or home not in parent.parents:
                break
            _retire_if_set_up(parent)
        if project.is_excluded(root, project.load_excludes(SHARED / "harness-exclude"), skip_file=False) \
                or skip_file_holds(root):
            return {"action": "skip", "why": "excluded", "root": str(root)}
        return setup(root, trigger)
    except Exception as exc:  # a trigger must never break its caller
        return {"action": "error", "why": "%s: %s" % (type(exc).__name__, exc)}


def skip_file_holds(root):
    """True when a .harness-skip keeps the engine out of root: one is there and `harness init`
    has not recorded an override of a committed copy."""
    return os.path.lexists(os.path.join(root, ".harness-skip")) and not _load_state(Path(root)).get("skip_override")


def lift_skip(root):
    """Let the engine back in after a .harness-skip, for `harness init`. Returns a note, or None.

    In a repository you have not trusted a committed .harness-skip belongs to the repository, and
    local mode never deletes or writes a tracked file. Your override goes into the engine's state
    instead, where `harness remove` (which rewrites that state) undoes it."""
    root = Path(root)
    if not os.path.lexists(root / ".harness-skip"):
        return None
    if _repo(root) is not None and not is_trusted(root) and _tracked_any(root, ".harness-skip"):
        state = _load_state(root)
        state["skip_override"] = True
        _save_state(_state_path(root), state)
        return ".harness-skip is tracked by git, so it stays; the engine ignores it on this machine until `harness remove`"
    try:
        safefs.remove(root, root / ".harness-skip")
    except (safefs.Unsafe, OSError):
        pass
    return None


def remove(root):
    """Undo what the engine wrote and keep it out. Your decisions and config stay; fieldbook is left alone.

    .harness-skip is written first, so even a partial failure leaves the project opted out.
    """
    with _one_scan():
        return _remove(Path(root))


def _remove(root):
    done, failed = [], []
    # A repo the engine skipped has no mode in its state, yet is still someone else's.
    state = _load_state(root)
    local = state.get("mode") == "local" or (_repo(root) is not None and not is_trusted(root))
    # Where the repo's own rules would show .harness-skip, the opt-out lives in the engine's state instead.
    # A tracked .harness-skip, under any spelling the disk folds together, is theirs too, even
    # when it is missing from the checkout: writing it would show as a change.
    skip_file = not local or (not _tracked_any(root, ".harness-skip") and _aliased(root, (".harness-skip",)) is None
                              and _hide_locally(root, _local_excludes(state)) and _ignored(root, [".harness-skip"]))

    def attempt(label, fn, rel=None):
        # In someone else's repository a tracked file is theirs, even one holding an engine block.
        # The check folds case: on a folding disk .HARNESS/CHANGELOG.md is the file a write to
        # .harness/CHANGELOG.md would change.
        if local and rel and safefs.exists(root, root / rel) and _tracked_any(root, rel):
            done.append("%s left: tracked by git" % rel)
            return
        try:
            if fn():
                done.append(label)
        except (safefs.Unsafe, OSError) as exc:
            failed.append("%s (%s)" % (label, exc))

    if skip_file:
        attempt(".harness-skip written", lambda: safefs.write_text(
            root, root / ".harness-skip", "Created by harness remove. Delete this file to let the engine set this project up again.\n"))
    else:
        try:
            _save_state(_state_path(root), {"removed": True, "engine": ENGINE_VERSION, "root": str(root)})
            done.append("opt-out written to the engine's state (a .harness-skip file would show in git status here)")
        except OSError as exc:
            failed.append("opt-out (%s)" % exc)
    # Local mode never wrote AGENTS.md or CLAUDE.md, so blocks found there are the repository's own.
    for mode in ("local",) if local else ("full", "local"):
        target, importer = _paths(root, mode)
        rel_t, rel_i = str(target.relative_to(root)), str(importer.relative_to(root))
        attempt("%s block" % rel_t, lambda t=target: remove_block(root, t, BEGIN, END), rel_t)
        attempt("%s import" % importer.name, lambda i=importer: remove_block(root, i, IMPORT_BEGIN, IMPORT_END), rel_i)
    attempt(".harness/CHANGELOG.md", lambda: safefs.remove(root, root / ".harness" / "CHANGELOG.md"), ".harness/CHANGELOG.md")
    if not (local and _tracked_any(root, ".harness/.born")):
        try:
            safefs.remove(root, root / ".harness" / ".born")
        except (safefs.Unsafe, OSError):
            pass
    decisions = safefs.read_text(root, root / ".harness" / "decisions.md")
    if decisions is not None and decisions.strip() == DECISIONS_TEMPLATE.strip():
        attempt(".harness/decisions.md (empty template)", lambda: safefs.remove(root, root / ".harness" / "decisions.md"),
                ".harness/decisions.md")
    if safefs.is_dir(root, root / ".harness"):
        if safefs.rmdir(root, root / ".harness"):
            done.append(".harness/")
        else:
            done.append(".harness/ kept (holds your decisions or config)")
    if skip_file:
        try:
            os.remove(_state_path(root))
        except OSError:
            pass
    elif not any(os.path.lexists(root / n) for n in (".harness", "CLAUDE.local.md")):
        _unhide(root)
    return done + ["FAILED: " + f for f in failed]
